using System.IO;
using System.Text.Json;
using System.Security.Cryptography;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace GymOS.Windows;
public sealed record ClubBrand(string Owner,string Name,string? Logo);
public sealed class DesktopBranding {
 readonly string root;public DesktopBranding(string rootPath){root=Path.GetFullPath(rootPath);Directory.CreateDirectory(root);}
 public ClubBrand? Load(){try{var value=JsonSerializer.Deserialize<ClubBrand>(File.ReadAllText(Path.Combine(root,"last-brand.json")));if(value!=null)Validate(value);return value;}catch{return null;}}
 public void Clear(){File.Delete(Path.Combine(root,"last-brand.json"));}
 static byte[]? Validate(ClubBrand brand){if(string.IsNullOrWhiteSpace(brand.Owner)||brand.Owner.Length>250||string.IsNullOrWhiteSpace(brand.Name)||brand.Name.Length>120||brand.Name.Any(char.IsControl))throw new InvalidOperationException("Invalid club branding");if(brand.Logo==null)return null;if(brand.Logo.Length>1400000||!brand.Logo.StartsWith("data:image/png;base64,",StringComparison.Ordinal))throw new InvalidOperationException("PNG logo required");var data=Convert.FromBase64String(brand.Logo[22..]);if(data.Length<24||!data.AsSpan(0,8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}))throw new InvalidOperationException("Invalid PNG");uint w=System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(data.AsSpan(16,4)),h=System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(data.AsSpan(20,4));if(w==0||h==0||w>4096||h>4096)throw new InvalidOperationException("Logo dimensions exceeded");return data;}
 public (BitmapSource? image,string? icon) Apply(ClubBrand brand,bool persist=true){var data=Validate(brand);BitmapSource? image=null;string? icon=null;if(data!=null){using var stream=new MemoryStream(data);var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.DecodePixelWidth=(int)Math.Min(1024,System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(data.AsSpan(16,4)));bitmap.StreamSource=stream;bitmap.EndInit();bitmap.Freeze();var visual=new DrawingVisual();RenderOptions.SetBitmapScalingMode(visual,BitmapScalingMode.HighQuality);using(var drawing=visual.RenderOpen()){double scale=Math.Min(256d/bitmap.PixelWidth,256d/bitmap.PixelHeight);var width=bitmap.PixelWidth*scale;var height=bitmap.PixelHeight*scale;drawing.DrawImage(bitmap,new Rect((256-width)/2,(256-height)/2,width,height));}var square=new RenderTargetBitmap(256,256,96,96,PixelFormats.Pbgra32);square.Render(visual);square.Freeze();image=bitmap;using var png=new MemoryStream();var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(square));encoder.Save(png);var content=png.ToArray();icon=Path.Combine(root,Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(brand.Owner+brand.Logo)))[..24]+".ico");using var output=File.Create(icon);using var writer=new BinaryWriter(output);writer.Write((ushort)0);writer.Write((ushort)1);writer.Write((ushort)1);writer.Write((byte)0);writer.Write((byte)0);writer.Write((byte)0);writer.Write((byte)0);writer.Write((ushort)1);writer.Write((ushort)32);writer.Write(content.Length);writer.Write(22);writer.Write(content);}if(persist){var file=Path.Combine(root,"last-brand.json");File.WriteAllText(file+".tmp",JsonSerializer.Serialize(brand));File.Move(file+".tmp",file,true);}return(image,icon);}
}
